import { callAssetApi } from '../../utils/server/assetApi';
import { presignStoreKey } from '../../utils/server/presignStore';
import { readStoreBytes, storeKeyFromUrl } from '../../utils/server/mediaStore';
import { registerAsset } from '../../utils/film/server/registerAsset';
import { assetFamilyOf, assetTypeOf, checkAssetBytes } from '../../utils/film/assetSpec';
import { VERIFY_LIMITS } from '../../utils/arkOfficialSpec';

// ModelArk official artifact verification (control-plane "Security audit" API):
// was this image or video generated by a ModelArk model?
//   POST { url, name } → CreateArkOfficialResultQuery → { queryId }
//   GET  ?queryId=…    → GetArkOfficialResult → { status, isOfficial, modelName, resourceType, resolution, message }
// The verifier downloads the file itself and cannot reach this app's TOS bucket, so an
// uploaded file (a media-store url) is registered in the Assets library first and
// verified by its Ark-hosted asset URL. Any other http(s) url is passed through as is.

const KEYS_MISSING = 'MODELARK_ASSET_ACCESS_KEY and MODELARK_ASSET_SECRET_KEY must both be set in .env.local (see .env.example).';

// IsOfficial arrives as "True" | "False" | "Null".
const verdictOf = (v) => {
  const s = String(v ?? '').trim().toLowerCase();
  return s === 'true' ? true : s === 'false' ? false : null;
};

// Both actions are rate-limited ("…beyond the current flow control limit"): back off and retry.
const callWithBackoff = async (args) => {
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await callAssetApi(args); // eslint-disable-line no-await-in-loop
    } catch (e) {
      if (attempt >= 4 || !/flow control/i.test(String(e.message))) throw e;
      await new Promise((r) => setTimeout(r, 1000 * 2 ** attempt)); // eslint-disable-line no-await-in-loop
    }
  }
};

// An uploaded file → a URL the verifier can fetch (its Assets-library copy).
const assetUrlForStoreKey = async ({ storeKey, name, keys }) => {
  const { buffer, contentType } = await readStoreBytes(storeKey);
  const family = assetFamilyOf(contentType);
  const limits = VERIFY_LIMITS[family];
  if (!limits) throw Object.assign(new Error('Only images and videos can be verified.'), { status: 400 });
  if (buffer.length > limits.maxBytes) {
    throw Object.assign(new Error(`${family} must be ${limits.maxBytes / (1024 * 1024)} MB or smaller to verify — this one is ${(buffer.length / (1024 * 1024)).toFixed(1)} MB.`), { status: 400 });
  }
  const specError = checkAssetBytes({ contentType, byteLength: buffer.length });
  if (specError) throw Object.assign(new Error(`Uploads are verified through the Assets library: ${specError} Paste a public URL instead.`), { status: 400 });
  const presigned = await presignStoreKey(storeKey);
  if (!presigned) throw new Error('The upload could not be presigned — check the TOS settings in .env.local.');
  const assetId = await registerAsset({ ...keys, url: presigned, name, assetType: assetTypeOf(contentType), waitForActive: true });
  if (!assetId) throw new Error('The Assets library returned no asset id.');
  const got = await callWithBackoff({ action: 'GetAsset', payload: { Id: assetId, ProjectName: 'default' }, ...keys });
  const url = got?.Result?.URL;
  if (got?.Result?.Status !== 'Active' || !url) throw new Error(`Asset ${assetId} is not ready (${got?.Result?.Status || 'no status'}).`);
  return { url, assetId };
};

export default async function arkOfficialHandler(req, res) {
  const accessKey = process.env.MODELARK_ASSET_ACCESS_KEY;
  const secretKey = process.env.MODELARK_ASSET_SECRET_KEY;
  if (!accessKey || !secretKey) return res.status(500).json({ error: KEYS_MISSING });
  const keys = { accessKey, secretKey };

  try {
    if (req.method === 'POST') {
      const raw = String(req.body?.url || '').trim();
      const storeKey = storeKeyFromUrl(raw);
      let url = raw;
      let assetId = null;
      if (storeKey) ({ url, assetId } = await assetUrlForStoreKey({ storeKey, name: req.body?.name, keys }));
      else if (!/^https?:\/\//i.test(raw)) return res.status(400).json({ error: 'Paste a public http(s) URL, or upload the file.' });
      const data = await callWithBackoff({ action: 'CreateArkOfficialResultQuery', payload: { Type: 'content_url', ContentURL: url }, ...keys });
      const queryId = data?.Result?.QueryID;
      if (!queryId) return res.status(502).json({ error: 'The verification query returned no QueryID.' });
      return res.status(200).json({ queryId, assetId });
    }

    if (req.method === 'GET') {
      const queryId = String(req.query.queryId || '').trim();
      if (!queryId) return res.status(400).json({ error: 'queryId is required' });
      const data = await callWithBackoff({ action: 'GetArkOfficialResult', payload: { QueryID: queryId }, ...keys });
      const r = data?.Result || {};
      return res.status(200).json({
        queryId: r.QueryID || queryId,
        status: r.Status || 'running', // running | succeeded | failed
        isOfficial: verdictOf(r.IsOfficial), // true | false | null (undetermined)
        resourceType: r.ResourceType || null,
        modelName: r.ModelName || null,
        resolution: r.Resolution || null,
        message: r.Message || '',
      });
    }

    res.setHeader('Allow', ['GET', 'POST']);
    return res.status(405).json({ error: `Method ${req.method} Not Allowed` });
  } catch (error) {
    return res.status(error.status || 500).json({ error: error.status ? error.message : `Verification failed: ${error.message}` });
  }
}
